"/projects/PuppyPi/en/latest/assets/image17.CgSBmw9p.webp",F="/projects/PuppyPi/en/latest/assets/image18.B-tS9aMf.webp",J="/projects/PuppyPi/en/latest/assets/image20.DiDlNsRo.webp",R="/projects/PuppyPi/en/latest/assets/image21.CCsMR99Q.webp",N="/projects/PuppyPi/en/latest/assets/image22.C42m4DnR.webp",U="/projects/PuppyPi/en/latest/assets/image23.CHDJ_OdM.webp",V="/projects/PuppyPi/en/latest/assets/image24.ClSPB6AN.webp",H="/projects/PuppyPi/en/latest/assets/image25.sEc_ilR8.webp",X="/projects/PuppyPi/en/latest/assets/image26.BwRcFYuJ.webp",K="/projects/PuppyPi/en/latest/assets/image2.BtjdiD-g.webp",M="/projects/PuppyPi/en/latest/assets/image3.BcuPvefK.webp",Z="/projects/PuppyPi/en/latest/assets/image4.DmDGm4l9.webp",Y="/projects/PuppyPi/en/latest/assets/image27.Bf8l5XDA.webp",_="/projects/PuppyPi/en/latest/assets/image5.HWZC2QW9.webp",$="/projects/PuppyPi/en/latest/assets/image6.svCLMSQe.webp",tt="/projects/PuppyPi/en/latest/assets/image7.BbugTGTC.webp",et="/projects/PuppyPi/en/latest/assets/image10.DxQMThBQ.webp",ot="/projects/PuppyPi/en/latest/assets/image11.-S1p6HP9.webp",it="/projects/PuppyPi/en/latest/assets/image12.ClLttV6c.webp",nt="/projects/PuppyPi/en/latest/assets/image13.Bcpr3aj1.webp",st="/projects/PuppyPi/en/latest/assets/image14.CEuj1CU_.webp",at="/projects/PuppyPi/en/latest/assets/image15.BnWiSzTs.webp",rt="data:image/png;base64,",lt="/projects/PuppyPi/en/latest/assets/image17.BkvGuCiv.webp",ct="data:image/png;base64,",dt="/projects/PuppyPi/en/latest/assets/image19.CUlRe7BJ.webp",gt="/projects/PuppyPi/en/latest/assets/image20.Dsz6Cz8f.webp",pt="/projects/PuppyPi/en/latest/assets/image21.BtQhasHW.webp",ht="/projects/PuppyPi/en/latest/assets/image22.mP2-qF-l.webp",mt="/projects/PuppyPi/en/latest/assets/image23.CcdC4yDc.webp",ut="/projects/PuppyPi/en/latest/assets/image24.BZ5f2PnW.webp",At="/projects/PuppyPi/en/latest/assets/image25.CSqj5NaW.webp",yt="/projects/PuppyPi/en/latest/assets/image25.CSqj5NaW.webp",Pt="/projects/PuppyPi/en/latest/assets/image2.cMMNUvrM.webp",Dt=JSON.parse('{"title":"2. APP and Handle Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.Quick_User_Experience.md","filePath":"docs/2.Quick_User_Experience.md"}'),bt={name:"docs/2.Quick_User_Experience.md"};function ft(wt,t,qt,vt,xt,kt){return r(),l("div",null,[...t[0]||(t[0]=[c('<h1 id="_2-app-and-handle-control" tabindex="-1">2. APP and Handle Control <a class="header-anchor" href="#_2-app-and-handle-control" aria-label="Permalink to &quot;2. APP and Handle Control&quot;">​</a></h1><p id="anchor_2_1"></p><h2 id="_2-1-app-installation-and-connection" tabindex="-1">2.1 APP Installation and Connection <a class="header-anchor" href="#_2-1-app-installation-and-connection" aria-label="Permalink to &quot;2.1 APP Installation and Connection&quot;">​</a></h2><p>The following instructions use TurboPi as an example and apply to other Hiwonder Raspberry Pi series products as well. In this section, you will learn how to use APP &quot;<strong>WonderPi</strong>&quot; to control TurboPi. The installation method is as follows.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p></li><li><p>Turn on Location and WiFi before operation.</p></li></ul></div><h3 id="_2-1-1-installation" tabindex="-1">2.1.1 Installation <a class="header-anchor" href="#_2-1-1-installation" aria-label="Permalink to &quot;2.1.1 Installation&quot;">​</a></h3><p><strong><a href="https://play.google.com/store/apps/details?id=com.Wonder.Pi" target="_blank" rel="noreferrer">APP Installation Pack (Android)</a></strong></p><p><strong><a href="https://apps.apple.com/cn/app/wonderpi/id1477946178" target="_blank" rel="noreferrer">APP Installation Pack (iOS)</a></strong></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Please turn TurboPi on before connecting.</p></li><li><p>Make sure all APP permissions are turned on in settings, otherwise APP functions will be limited!</p></li><li><p>Turn on Location and WiFi before operation.</p></li></ul></div><h3 id="_2-1-2-app-connection" tabindex="-1">2.1.2 APP Connection <a class="header-anchor" href="#_2-1-2-app-connection" aria-label="Permalink to &quot;2.1.2 APP Connection&quot;">​</a></h3><p>(1) Start robot. (The switch is on Raspberry Pi expansion board). For detailed instruction, please refer to the file in &quot;<a href="./1.Quick_Start_Guide.html#start-puppypi"><strong>1. Quick Start Guide / 1.3 Start PuppyPi</strong></a>&quot;.</p><p>(2) After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>. Join this WiFi, and then you can experience robot games</p><ul><li><strong>Introduction to Connection Mode</strong></li></ul><p>There are two connection modes, namely direct connection mode and LAN mode. APP functions are the same under these two modes.</p><p>(1) AP direct connection mode: RaspberryPi generates a WiFi which can be connected by phones. But this WiFi has no internet access.</p><p>(2) STA LAN mode: Raspberry Pi actively connects to specific WiFi. In this mode, you can access internet.</p><ul><li><strong>Direct Connection Mode (MUST-READ)</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>After TurboPi boots up successfully, it enters AP direct connection mode, and generates a WiFi starting with <strong>&quot;HW&quot;</strong>.</p></div><p>(1) Open&quot;<strong>WonderPi</strong>&quot;. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+d+'"><p>(2) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select <strong>Direct Connection Mode</strong>.</p><img loading="lazy" src="'+g+'"><p>(3) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>. Join WiFi starting with &quot;<strong>HW</strong>&quot;. The password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" src="'+p+'"><img loading="lazy" src="'+e+'" style="width:350px;" class="common_img"><p>(4) Return back to APP after connection.</p><img loading="lazy" src="'+o+'" style="width:350px;" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>for iOS user, please don&#39;t return to APP until WiFi icon appears on status bar, otherwise robot cannot be searched. If robot cannot be searched by APP, tap <img loading="lazy" height="52" width="52" src="'+h+'" style="width:45px;"> to refresh.</p></div><p>(5) APP automatically connects to robot. When robot icon below occurs, connection completes.</p><img loading="lazy" src="'+m+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>if you are informed of <strong>&quot;No Internet. Whether to keep connection&quot;,</strong> just select &quot;<strong>keep connected</strong>&quot;.</p></div><p>(6) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+u+'"><p>For detailed introduction to robot games, please refer to the file in &quot;<strong><a href="#anchor_2_2">2.2 Start AI Games via APP</a></strong>&quot;.</p><ul><li><strong>LAN Connection Mode</strong></li></ul><p>(1) Disconnect the WiFi generated by TurboPi. Connect your phone to a WiFi. Take <strong>&quot;Hiwonder&quot;</strong> as example.</p><img loading="lazy" src="'+A+'" style="width:350px;" class="common_img"><p>(2) After connection, open <strong>&quot;WonderPi&quot;</strong>. Select <strong>&quot;Standard -&gt;TurboPi&quot;</strong> in sequence.</p><img loading="lazy" src="'+y+'"><p>(3) Tap <strong>&quot;+&quot;</strong> in bottom right corner, and then select LAN Mode.</p><img loading="lazy" src="'+P+'"><p>(4) Input the password of the WiFi your phone joins. Ensure the password you input is correct, otherwise APP fails to connect to robot. Tap <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" src="'+b+'"><p>(5) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>.</p><img loading="lazy" src="'+f+'"><p>(6) Join the WiFi starting with <strong>&quot;HW&quot;.</strong> The password is <strong>&quot;hiwonder&quot;</strong>. After connection, return back to APP.</p><p class="common_img" style="text-align:center;"><img loading="lazy" src="'+e+'" style="width:420px;"><img loading="lazy" src="'+o+'" style="width:420px;"></p><p>(7) APP automatically configures network.</p><img loading="lazy" src="'+w+'"><p>(8) After a while, robot icon below occurs, and LED on expansion board keeps on.</p><img loading="lazy" src="'+q+'"><p>(9) Long press robot icon to check TurboPi&#39;s IP and ID.</p><img loading="lazy" src="'+v+'"><p>(10) Tap robot icon to enter mode selection interface.</p><img loading="lazy" src="'+x+'"><p>For detailed introduction to robot games, please refer to the file in&quot;<strong>2.2 APP Start AI Games via APP</strong>&quot;.</p><p id="anchor_2_2"></p><h2 id="_2-2-start-ai-games-via-app" tabindex="-1">2.2 Start AI Games via APP <a class="header-anchor" href="#_2-2-start-ai-games-via-app" aria-label="Permalink to &quot;2.2 Start AI Games via APP&quot;">​</a></h2><h3 id="_2-2-1-getting-ready" tabindex="-1">2.2.1 Getting Ready <a class="header-anchor" href="#_2-2-1-getting-ready" aria-label="Permalink to &quot;2.2.1 Getting Ready&quot;">​</a></h3><p>Please install the APP and connect it to PuppyPi according to &quot;<a href="#anchor_2_1"><strong>2.1 APP Installation and Connection</strong></a>&quot;.</p><h3 id="_2-2-2-have-a-try" tabindex="-1">2.2.2 Have a Try <a class="header-anchor" href="#_2-2-2-have-a-try" aria-label="Permalink to &quot;2.2.2 Have a Try&quot;">​</a></h3><p>Click the PuppyPi icon to enter the game selection interface.</p><img loading="lazy" height="394" width="777" class="common_img" src="'+k+'" alt="loading"><img loading="lazy" height="412" width="799" class="common_img" src="'+j+'" alt="loading"><img loading="lazy" height="412" width="801" class="common_img" src="'+D+'" alt="loading"><ul><li><strong>Remote Control</strong></li></ul><p>(1) Select <strong>&quot;Remote Control&quot;</strong>. When we successfully enter the game interface, PuppyPi will return to initial posture. There are two modes, including normal mode and advanced mode.</p><p>① In normal mode, you can control PuppyPi to do some simple movements through dragging the button.</p><img loading="lazy" height="421" width="810" class="common_img" src="'+z+'" alt="loading"><p>② In advanced mode, PuppyPi&#39;s motion speed, height and posture can be controlled.</p><img loading="lazy" height="414" width="799" class="common_img" src="'+T+'" alt="loading"><p>The functions of the buttons under different modes are listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Mode</strong></th><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">Normal mode</td><td style="text-align:center;"><img loading="lazy" src="'+i+'"></td><td style="text-align:center;">Drag the button to control PuppyPi&#39;s moving direction</td></tr><tr><td style="text-align:center;">Advanced mode</td><td style="text-align:center;"><img loading="lazy" height="119" width="120" src="'+B+'" style="width:180px;"></td><td style="text-align:center;">Display the level of speed from 0 to 10</td></tr><tr><td style="text-align:center;">Advanced mode</td><td style="text-align:center;"><img loading="lazy" src="'+i+'"></td><td style="text-align:center;">Drag the button to control PuppyPi&#39;s motion speed. The further you drag the button, the faster PuppyPi moves.</td></tr><tr><td style="text-align:center;">Advanced mode</td><td style="text-align:center;"><img loading="lazy" height="74" width="369" src="'+C+'"></td><td style="text-align:center;">Drag the slider to adjust the Pitch angle</td></tr><tr><td style="text-align:center;">Advanced mode</td><td style="text-align:center;"><img loading="lazy" height="240" width="98" src="'+E+'"></td><td style="text-align:center;">Drag the slider to adjust PuppyPi&#39;s height.</td></tr><tr><td style="text-align:center;">general</td><td style="text-align:center;"><img loading="lazy" height="75" width="79" src="'+Q+'" style="width:100px;"></td><td style="text-align:center;">Capture the current camera returned image and save it to phone gallery</td></tr><tr><td style="text-align:center;">general</td><td style="text-align:center;"><img loading="lazy" height="81" width="83" src="'+S+'" style="width:100px;"></td><td style="text-align:center;">Hide the top menu bar</td></tr><tr><td style="text-align:center;">general</td><td style="text-align:center;"><img loading="lazy" height="86" width="107" src="'+I+'" style="width:100px;"></td><td style="text-align:center;">Contact with Hiwonder team(<a href="mailto:support@hiwonder.com" target="_blank" rel="noreferrer">support@hiwonder.com</a>) for more information</td></tr></tbody></table><p>(2) If you want to return to the game selection interface, click the blank area to make the menu bar pop up. Then click <img loading="lazy" height="41" width="51" src="'+n+'" style="width:70px;"> to go back to the game selection interface.</p><ul><li><strong>Performance Mode</strong></li></ul><p>(1) Click <strong>&quot;Performance Mode&quot;</strong> to enter the game interface. The interface is divided into two parts.</p><p>① At the left side, it is the action list consisting of built-in actions and customized actions.</p><p>② At the right side, it is the self-balancing area.</p><img loading="lazy" height="420" width="799" class="common_img" src="'+G+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>For how to customize action, please refer to the tutorial in &quot;<a href="./10.ROS1_AI_Vision_Line_Following_Course.html#app-customized-control"><strong>5. ROS1-PC Software Action Editing Course-&gt;5.6 APP Customized Control</strong></a>&quot;.</p></div><p>(2) Select the actions at left randomly, and then PuppyPi will execute the corresponding action.</p><p>(3) Click <strong>&quot;keep balance&quot;</strong> button at right to make PuppyPi adjust and balance its posture automatically according to the tilt of surface.</p><p>The functions of buttons are as follow.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="61" width="122" src="'+O+'" style="width:500px;" alt="loading"></td><td style="text-align:center;">Take <strong>&quot;Lie Down&quot;</strong> for example. When we click this button, PuppyPi will lie down.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="92" width="166" src="'+W+'" style="width:500px;" alt="loading"></td><td style="text-align:center;"><strong>&quot;keep balance&quot;</strong> function.<br> (Note: The tilt should not exceed 30 degree.)</td></tr></tbody></table><p>(4) If you want to return to the game selection interface, click the blank area to make the menu bar pop up. Then click <img loading="lazy" height="41" width="51" src="'+n+'" style="width:70px;"> to go back to the game selection interface.</p><ul><li><strong>Object Tracking</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Please operate in the well-lit indoor and avoid the direct glare</li><li>Apart from the target object, please remove other stuffs in same or similar color to the target to avoid disturbance.</li></ul></div><p>(1) On the mode selection screen, tap <strong>&quot;Object Tracking&quot;</strong> to enter the feature interface. Using a red ball as an example, tap the <strong>&quot;Pick&quot;</strong> button to select the target color.</p><img loading="lazy" height="399" width="776" class="common_img" src="'+L+'" alt="loading"><img loading="lazy" height="401" width="784" class="common_img" src="'+s+'"><p>(2) The selected color will be displayed under &quot;<strong>Selected Color</strong>&quot; for confirmation.</p><img loading="lazy" height="401" width="784" class="common_img" src="'+s+'"><p>(3) Tap &quot;Start&quot; to begin tracking. Once activated, the robot will follow the movement of the selected object.</p><img loading="lazy" height="402" width="781" class="common_img" src="'+F+'"><ul><li><strong>Target Tracking</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Please operate in the well-lit indoor and avoid the direct glare</li><li>Apart from the target object, please remove other stuffs in same or similar color to the target to avoid disturbance.</li></ul></div><p>To get started, tap <strong>&quot;Tag Recognition&quot;</strong> to enter the feature interface, then tap <strong>&quot;Start&quot;</strong> to initiate the process. Once activated, hold the included label cards one at a time in front of the camera. When a card is successfully recognized, the robot will automatically perform the corresponding action.</p><img loading="lazy" height="543" width="1042" class="common_img" src="'+J+'" alt="loading" style="width:780px;"><table class="docutils-nobg" border="1"><thead><tr><th>Tag ID</th><th>1</th><th>2</th><th>3</th></tr></thead><tbody><tr><td>Executed action</td><td>Greetings</td><td>Lie down</td><td>Push up</td></tr></tbody></table><ul><li><strong>Face Detection</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Please operate in the well-lit indoor</li><li>Please ensure the tag is intact. Missing part and dirt will influence the recognition result.</li></ul></div><img loading="lazy" height="403" width="779" class="common_img" src="'+R+'" alt="loading"><ul><li><strong>Line Following</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Use tape to lay out the line-following track.</p></li><li><p>Ensure the color selection range is appropriate—not too broad or too narrow—and avoid having objects with similar colors to the target within the camera’s field of view.</p></li></ul></div><p>(1) On the mode selection screen, tap <strong>&quot;Line Following&quot;</strong> to enter the operation interface. Using red tape as an example, tap the <strong>&quot;Pick&quot;</strong> button.</p><img loading="lazy" height="411" width="796" class="common_img" src="'+N+'" alt="loading"><p>(2) Drag the red circle within the live video feed to the track area to select the color, then tap &quot;<strong>OK</strong>&quot; button.</p><img loading="lazy" height="414" width="797" class="common_img" src="'+U+'"><p>(3) The currently selected color will be displayed under <strong>&quot;Selected Color&quot;</strong>.</p><img loading="lazy" height="416" width="804" class="common_img" src="'+V+'"><p>(4) Tap <strong>&quot;Start&quot;</strong> to begin. The robot will then follow the track accordingly.</p><img loading="lazy" height="419" width="802" class="common_img" src="'+H+'"><ul><li><strong>Lidar</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Place the robot on a wide, flat surface to ensure it has sufficient space to move safely.</p></li><li><p>Obstacles should be taller than the robot to ensure proper detection and response.</p></li></ul></div><p>(1) Click <strong>&quot;Line Following&quot;</strong> to enter the game interface. The game interface is divided into two parts.</p><p>① At left, it is the button to start or stop the game.</p><p>② At right, it is the real-time image transmitted by camera.</p><img loading="lazy" height="414" width="801" class="common_img" src="'+X+'"><table class="docutils-nobg" border="1"><thead><tr><th>Feature</th><th>How it Works</th></tr></thead><tbody><tr><td>Lidar Obstacle Avoidance</td><td>The robot automatically changes direction when it detects an obstacle, helping it navigate safely.</td></tr><tr><td>Lidar Following</td><td>The robot tracks and adjusts its position to stay at a steady distance from the object ahead.</td></tr><tr><td>Lidar guarding</td><td>When an object is detected, the robot turns to face it, staying alert and responsive.</td></tr></tbody></table><p id="anchor_2_3"></p><h2 id="_2-3-adjust-color-threshold" tabindex="-1">2.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3 Adjust Color Threshold&quot;">​</a></h2><p>Different light source will have different influence on the colors, which will result in recognition discrepancy. To tackle this problem, you can adjust color threshold via &quot;<strong>WonderPi</strong>&quot; APP.</p><h3 id="_2-3-1-preparation" tabindex="-1">2.3.1 Preparation <a class="header-anchor" href="#_2-3-1-preparation" aria-label="Permalink to &quot;2.3.1 Preparation&quot;">​</a></h3><p>Start TurboPi. Open &quot;<strong>WonderPi</strong>&quot; APP, and connect it to TurboPi. For how to connect robot to APP, operate referring to &quot;<strong><a href="#anchor_2_1">2.1 APP Installation and Connection</a></strong>&quot;.</p><h3 id="_2-3-2-interface-layout" tabindex="-1">2.3.2 Interface Layout <a class="header-anchor" href="#_2-3-2-interface-layout" aria-label="Permalink to &quot;2.3.2 Interface Layout&quot;">​</a></h3><p>Tap in upper right corner to enter color threshold adjustment interface.</p><img loading="lazy" src="'+K+'"><img loading="lazy" height="520" width="1100" src="'+M+'"><p>The table below list function of specific icon.</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td><strong>Icon</strong></td><td><strong>Function</strong></td></tr><tr><td><img loading="lazy" height="1184" width="1556" src="'+Z+'" style="width:300px;"></td><td><p>Processed camera returned image.</p><p>Target object is white, and other area is black.</p></td></tr><tr><td><img loading="lazy" height="286" width="383" src="'+Y+'" style="width:290px;"></td><td>Raw camera returned image.</td></tr><tr><td><img loading="lazy" height="75" width="346" src="'+_+'" style="width:200px;"></td><td>Select the color to be adjusted.</td></tr><tr><td><img loading="lazy" height="85" width="346" src="'+$+'" style="width:200px;"><img loading="lazy" height="84" width="346" src="'+tt+'" style="width:200px;"></td><td><p>Adjust L component of camera returned image. &quot;<b>L_min</b>&quot; is lower limit and &quot;<b>L_max</b>&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="85" width="346" src="'+et+'" style="width:200px;"><img loading="lazy" height="83" width="346" src="'+ot+'" style="width:200px;"></td><td><p>Adjust A component of camera returned image. &quot;<b>a_min</b>&quot; is lower limit and &quot;<b>a_max</b>&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="84" width="346" src="'+it+'" style="width:200px;"><img loading="lazy" height="85" width="346" src="'+nt+'" style="width:200px;"></td><td><p>Adjust B component of camera returned image. &quot;<b>b_min</b>&quot; is lower limit and &quot;<b>b_max</b>&quot; is upper limit.</p></td></tr><tr><td><img loading="lazy" height="84" width="162" src="'+st+'" style="width:200px;"></td><td>Get instruction to check how to adjust color threshold.</td></tr><tr><td><img loading="lazy" height="87" width="144" src="'+at+'" style="width:100px;"></td><td>Save the adjusted color threshold.</td></tr><tr><td><img loading="lazy" height="87" width="87" src="'+rt+'" style="width:60px;"></td><td>Return back to mode selection interface.</td></tr><tr><td><img loading="lazy" height="87" width="86" src="'+lt+'" style="width:60px;"></td><td>Hide navigation bar.</td></tr><tr><td><img loading="lazy" height="86" width="86" src="'+ct+'" style="width:60px;"></td><td>Display Hiwonder info.</td></tr></tbody></table><h3 id="_2-3-3-adjust-color-threshold" tabindex="-1">2.3.3 Adjust Color Threshold <a class="header-anchor" href="#_2-3-3-adjust-color-threshold" aria-label="Permalink to &quot;2.3.3 Adjust Color Threshold&quot;">​</a></h3><p>(1) Select color to be adjusted. Take red as example.</p><img loading="lazy" height="517" width="1100" src="'+dt+'"><p>(2) Put red object within camera recognition zone. Set L_min, a_min and b_min to 0, and L_max, a_max and b_max to 255.</p><img loading="lazy" height="530" width="1100" src="'+gt+'"><p>(3) Tap &quot;<strong>Instruction</strong>&quot; icon to check how to adjust color threshold.</p><img loading="lazy" height="524" width="1100" src="'+pt+'"><img loading="lazy" height="560" width="1213" src="'+ht+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>if you need to close Instruction window, select &quot;<strong>OK</strong>&quot;.</p></div><p>(4) Red approaches &quot;<strong>+a</strong>&quot; zone, so you need to adjust A component.</p><img loading="lazy" height="300" width="300" src="'+mt+'" style="width:300px;" class="common_img"><p>(5) Keep &quot;<strong>a_max</strong>&quot; value the same, and then increase &quot;<strong>a_min</strong>&quot; value till red object turns white and other area is black.</p><img loading="lazy" height="602" width="1280" src="'+ut+'"><p>(6) Adjust &quot;<strong>L</strong>&quot; and &quot;<strong>B</strong>&quot; values. If it belongs to light red, increase L_min. Otherwise, decrease L_max. If it belongs to warm tone, increase B_min. Otherwise, decrease B_max.</p><img loading="lazy" height="602" width="1280" src="'+At+'"><p>(7) Remember to save the value after adjustment.</p><img loading="lazy" height="602" width="1280" src="'+yt+'"><h2 id="_2-4-wireless-handle-control" tabindex="-1">2.4 Wireless Handle Control <a class="header-anchor" href="#_2-4-wireless-handle-control" aria-label="Permalink to &quot;2.4 Wireless Handle Control&quot;">​</a></h2><h3 id="_2-4-1-getting-ready" tabindex="-1">2.4.1 Getting Ready <a class="header-anchor" href="#_2-4-1-getting-ready" aria-label="Permalink to &quot;2.4.1 Getting Ready&quot;">​</a></h3><p>(1) Step 1: insert the handle receiver into any USB interface on PuppyPi.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>please insert the handle receiver before the device boots up.</p></div><p>(2) Step 2: please bring your own two AAA dry batteries. And insert them into the battery slot and please don&#39;t invert the positive and negative electrode.</p><img loading="lazy" height="482" width="1288" class="common_img" src="'+Pt+'" alt="loading"><h3 id="_2-4-2-device-connection" tabindex="-1">2.4.2 Device connection <a class="header-anchor" href="#_2-4-2-device-connection" aria-label="Permalink to &quot;2.4.2 Device connection&quot;">​</a></h3><p>(1) Turn on PuppyPi.</p><p>(2) Turn on the switch on the handle. At this time, two LED lights will flash simultaneously.</p><p>(3) Please wait for a while. Then the robot will pair with the handle automatically. After successful pairing, the green light will keep lighting up.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the handle doesn&#39;t connect to the robot within 30s or there is no operation on the handle within 5 minutes after turning on, it will enter sleep mode. And you can press &quot;<strong>START</strong>&quot; to activate the handle.</p></div><h3 id="_2-4-3-key-function" tabindex="-1">2.4.3 Key Function <a class="header-anchor" href="#_2-4-3-key-function" aria-label="Permalink to &quot;2.4.3 Key Function&quot;">​</a></h3><p>The functions of the keys are listed below.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Key</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">PuppyPi returns to initial posture</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">raise its head</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">bend its head</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">tilt forward</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">tilt backward</td></tr><tr><td style="text-align:center;">↑ / Drag the left joystick upwards</td><td style="text-align:center;">move forward</td></tr><tr><td style="text-align:center;">↓ / Drag the left joystick downwards</td><td style="text-align:center;">move backward</td></tr><tr><td style="text-align:center;">← / Drag the left joystick to left</td><td style="text-align:center;">turn left</td></tr><tr><td style="text-align:center;">→ / Drag the left joystick to right</td><td style="text-align:center;">turn right</td></tr><tr><td style="text-align:center;">△ / Drag the right joystick upwards</td><td style="text-align:center;">increase body height</td></tr><tr><td style="text-align:center;">× / Drag the right joystick downwards</td><td style="text-align:center;">decrease body height</td></tr><tr><td style="text-align:center;">◻ / Drag the right joystick to left</td><td style="text-align:center;">speed down (combine with the &quot;<strong>↑</strong>&quot; and &quot;<strong>↓</strong>&quot; button)</td></tr><tr><td style="text-align:center;">○ / Drag the right joystick to right</td><td style="text-align:center;">speed up (combine with the &quot;<strong>↑</strong>&quot; and &quot;<strong>↓</strong>&quot; button)</td></tr></tbody></table>',161)])])}const zt=a(bt,[["render",ft]]);export{Dt as __pageData,zt as default};
